    public string GetPropertyToString(string name)
    {
        // ★ 修复（2026-08-12）：mpv_get_property_string 返回的 char* 由 mpv 内部（talloc）分配，
        //   必须用 mpv_free 释放。此前声明为 string 返回值时，LibraryImport 源生成器生成的代码
        //   会用 Utf8StringMarshaller.Free（内部 Marshal.FreeHGlobal）错误释放该指针，与 mpv
        //   分配器不匹配导致堆损坏（0xc0000374，故障模块 ntdll.dll）。
        //   现改为 IntPtr 返回 + 手动 PtrToStringUTF8 + mpv_free。
        var ptr = mpv_get_property_string(Handle, name);
        if (ptr == IntPtr.Zero)
        {
            return string.Empty;
        }

        try
        {
            return Marshal.PtrToStringUTF8(ptr) ?? string.Empty;
        }
        finally
        {
            MpvStatics.Free(ref ptr);
        }
    }

