    /// </summary>
    /// <param name="isTerminate"><c>true</c> indicates that destroy all clients.</param>
    public Task DestroyAsync(bool isTerminate = false)
    {
        return Task.Run(() =>
        {
            if (isTerminate || IsCore)
            {
                mpv_terminate_destroy(Handle);
            }
            else
            {
                mpv_destroy(Handle);
            }

            IsInitialized = false;
        });
    }

